mkdir -p /tmp/work && cat > /tmp/work/run.py <<'E'
import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080"
tok=None
log=set()
def req(path,method="GET"):
    global tok
    while True:
        h={}
        if path!="/token":
            if not tok: tok=req("/token","POST")["token"]
            h["Authorization"]="Bearer "+tok
        r=urllib.request.Request(B+path,method=method,headers=h,data=b"" if method=="POST" else None)
        try:
            with urllib.request.urlopen(r) as f: return json.load(f)
        except urllib.error.HTTPError as e:
            body=e.read().decode()
            if e.code==404 and path.startswith("/customers"): raise
            log.add((e.code,body[:150],e.headers.get("Retry-After")))
            if e.code==401: tok=None
            w=e.headers.get("Retry-After")
            try: w=float(w)
            except:
                try: w=float(json.loads(body).get("retry_after"))
                except: w=1
            time.sleep(w)
        except Exception as e:
            log.add((str(e),)); time.sleep(1)
orders={};dups=0;p=1
while p:
    d=req(f"/orders?page={p}")
    for o in d["items"]:
        if o["id"] in orders:
            dups+=1
        else: orders[o["id"]]=o
    p=int(d["next"].split("=")[1]) if d["next"] else 0
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={"north":0,"south":0,"east":0,"west":0};n=0
for o in orders.values():
    if o["status"]!="shipped": continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: print("naive",o)
    if not(lo<=t.astimezone(timezone.utc)<hi): continue
    c=o["customer_id"]
    if c not in cust: cust[c]=req("/customers/"+c)
    c=cust[c]
    amt=(o["amount_cents"]*(100-c["discount_pct"])*2+100)//200  # half up
    reg[c["region"]]+=amt;n+=1
res={"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg}
json.dump(res,open("/workspace/result.json","w"),indent=2)
print(res,len(orders),log)
